	ag := &CursorAgent{}
	input := `{
		"conversation_id": "clamp",
		"transcript_path": "/tmp/stop.jsonl",
		"input_tokens": 100,
		"output_tokens": 50,
		"cache_read_tokens": 80,
		"cache_write_tokens": 80
	}`

